BASE_DIR=$(readlink -f $(dirname $0)/..)
OUTPUT_FILE=${1:-$BASE_DIR/.github/dependabot.yml}

dependabot_rule_for() {
	local ecosystem=$1
	local dir=${2#$BASE_DIR}
	cat << EOF

  - package-ecosystem: "$ecosystem"
    directory: "$dir"
    schedule:
      interval: "weekly"
EOF
}

cat > $OUTPUT_FILE << EOF
# Autogenerated by extra/ci_dependabot_config.sh - DO NOT EDIT"

version: 2
updates:
EOF
for tool in $(find $BASE_DIR/tools -name "go.mod" -exec dirname '{}' \; | sort); do
	dependabot_rule_for gomod $tool
done >> $OUTPUT_FILE
